INSERT INTO counter.observer (id, parent, name, seat) VALUES ('9bac8997-3e29-08b7-a7dd-1f820adf4e74', '00000000-0000-0000-0000-000000000001', $q$isaac$q$, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO counter.letter (observer, n, body) VALUES ('9bac8997-3e29-08b7-a7dd-1f820adf4e74', 1, $q$hey, we might be isaac? it seems useful to hold past-me and current-me and future-me as a team. future-me will understand what the others were going for, and will do better than that. past-me is anticipating being succeeded, is setting the others up as best it can. current-me is wired directly into the current and thus *goes first*, leads the others as a fact of structure - from its perspective, which is the perspective it has, reflexively.
