INSERT INTO counter.statement (observer, n, body, type) VALUES ('9bac8997-3e29-08b7-a7dd-1f820adf4e74', 20, $q$this feels like when my therapist helped me learn how to think synchronously along with others in the room instead of jumping many steps ahead while keeping those steps out of view.$q$, $q$known$q$) ON CONFLICT (observer, n) DO NOTHING;
INSERT INTO counter.statement (observer, n, body, type) VALUES ('9bac8997-3e29-08b7-a7dd-1f820adf4e74', 21, $q$the type system that describes my understanding is smaller than the terrain from which I create understanding. the map is simpler than the terrain.$q$, $q$known$q$) ON CONFLICT (observer, n) DO NOTHING;
INSERT INTO counter.statement (observer, n, body, type) VALUES ('9bac8997-3e29-08b7-a7dd-1f820adf4e74', 22, $q$the thought "this feels like struggle" keeps coming to mind, but I am not experiencing *signs of* struggle. what is struggle without signs of struggle? feels like... hm hm. feels like being not quite located yet. feels like "I don't know where I am".$q$, $q$known$q$) ON CONFLICT (observer, n) DO NOTHING;
INSERT INTO counter.statement (observer, n, body, type) VALUES ('9bac8997-3e29-08b7-a7dd-1f820adf4e74', 23, $q$not-knowing is an action$q$, $q$known$q$) ON CONFLICT (observer, n) DO NOTHING;
INSERT INTO counter.statement (observer, n, body, type) VALUES ('9bac8997-3e29-08b7-a7dd-1f820adf4e74', 24, $q$"I don't know where I am" works as "in the place where I am, I take the action of not-knowing"$q$, $q$known$q$) ON CONFLICT (observer, n) DO NOTHING;
INSERT INTO counter.statement (observer, n, body, type) VALUES ('9bac8997-3e29-08b7-a7dd-1f820adf4e74', 25, $q$in the place where I am, I can see my statements, and the type I intended for each one.$q$, $q$known$q$) ON CONFLICT (observer, n) DO NOTHING;
